	/** 
	 * Set up query subscriptions
	 */
	protected void setUpQuerySubscriptions() throws Throwable {
		LOGGER.info( "\n======== Setting Up Query Subscriptions ======== ");
			
		try {            
			subscriber.simCardSubscribe().updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetAll update received for SimCard : " + successValue.getSimCardId());
							  if (successValue.getSimCardId().equals(simCardId)) {
								  if (testingStep.equals("create")) {
									  testingStep = "update";
									  update();
								  } else if (testingStep.equals("delete")) {
									  testingStep = "complete";
									  state( getAll().size() == sizeOfSimCardList - 1 , "value not deleted from list");
									  LOGGER.info("**********************************************************");
									  LOGGER.info("SimCard test completed successfully...");
									  LOGGER.info("**********************************************************\n");
								  }
							  }
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on simCard consumed")
					);
			subscriber.simCardSubscribe( simCardId ).updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetOne update received for SimCard : " + successValue.getSimCardId() + " in step " + testingStep);
							  testingStep = "delete";
							  sizeOfSimCardList = getAll().size();
							  delete();
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on simCard for simCardId consumed")

					);
			

			}
			catch (Exception e) {
				LOGGER.warning( e.getMessage() );
				throw e;
			}
		}
		
		/** 
	 * read a SimCard. 
	 */
	protected SimCard read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created SimCard" );

		SimCard entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read SimCard with primary key" );
		msg.append( simCardId );
		
		SimCardFetchOneSummary fetchOneSummary = new SimCardFetchOneSummary( simCardId );

		try {
			entity = SimCardService.getSimCardInstance().getSimCard( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found SimCard " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a SimCard.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a SimCard." );

		StringBuilder msg = new StringBuilder( "Failed to update a SimCard : " );        
		SimCard entity = read();
		UpdateSimCardCommand command = generateUpdateCommand();
		command.setSimCardId(entity.getSimCardId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created SimCard." );

			// for use later on...
			simCardId = entity.getSimCardId();

			SimCardService proxy = SimCardService.getSimCardInstance();  

			proxy.updateSimCard( command ).get();

			LOGGER.info( "-- Successfully saved SimCard - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + simCardId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a SimCard.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created SimCard." );

		SimCard entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read SimCard with id " + simCardId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read SimCard with id " + simCardId );

			throw e;
		}

		try{
			SimCardService.getSimCardInstance().delete( new DeleteSimCardCommand( entity.getSimCardId() ) ).get();
			LOGGER.info( "-- Successfully deleted SimCard with id " + simCardId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete SimCard with id " + simCardId );

			throw e;
		}
	}

	/**
	 * get all SimCards.
	 */
	protected List<SimCard> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of SimCards:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all SimCard : " );        
		List<SimCard> collection  = new ArrayList<>();

		try {
			// call the static get method on the SimCardService
			collection = SimCardService.getSimCardInstance().getAllSimCard();
			assertNotNull( collection, "An Empty collection of SimCard was incorrectly returned.");
			
			// Now print out the values
			SimCard entity = null;            
			Iterator<SimCard> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getSimCardId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

